/**
 * RCP-03 레시피 추가 / RCP-04 수정 — 같은 폼이다(`?id=` 유무로 갈린다).
 *
 * 손익 미리보기는 `@margincook/core` 공식으로 즉시 계산하고, **확정값은 저장 시 서버**가 낸다.
 * 두 공식이 어긋나면 저장 전후 숫자가 달라지므로 core 와 SQL 의 식이 같아야 한다(절대원칙 3).
 */
import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { Alert, Pressable, ScrollView, Text, View } from 'react-native';
import { type Href, useLocalSearchParams, useRouter } from 'expo-router';
import { AppHeader, Badge, Button, Card, Field, Icon, Input, QueryState, Select, Sheet } from '@/components/kit';
import { safeBack } from '@/lib/nav';
import { formatPercent, formatQuantity, formatUnitPrice, recommendedPrice, round, taxAmount, taxRate } from '@margincook/core';
import { T, won } from '@/theme/tokens';
import { clampDecimals } from '@/lib/num';
import { useSettingsLists } from '@/features/master-data/hooks';
import { useStoreSettings } from '@/features/settings/hooks';
import { useRecipeDetail, useSaveRecipe } from '../hooks';
import { emptyDraft, useRecipeDraft, type DraftLine } from '../draftStore';

const NUM = { fontVariant: ['tabular-nums' as const] };

const num = (s: string) => {
  const n = parseFloat(String(s).replace(/,/g, ''));
  return Number.isNaN(n) ? 0 : n;
};

function SecHead({ title, sub, right }: { title: string; sub?: string; right?: ReactNode }) {
  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, paddingVertical: 13, paddingHorizontal: 15, backgroundColor: T.surface2, borderBottomWidth: 1, borderBottomColor: T.line2 }}>
      <Text style={{ fontSize: 16, fontWeight: '800', color: T.sub }}>{title}</Text>
      {sub ? <Text style={{ fontSize: 14, color: T.ter, fontWeight: '600' }}>{sub}</Text> : null}
      {right ? (<><View style={{ flex: 1 }} />{right}</>) : null}
    </View>
  );
}

function InfoBtn({ active, onPress }: { active: boolean; onPress: () => void }) {
  return (
    <Pressable onPress={onPress} hitSlop={6} style={{ padding: 2 }} accessibilityRole="button" accessibilityLabel="설명 보기">
      <Icon name="info" size={14} color={active ? T.blue : T.ter} />
    </Pressable>
  );
}

function Footer({ children }: { children: ReactNode }) {
  return (
    <View style={{ paddingVertical: 12, paddingHorizontal: 15, backgroundColor: T.surface2, borderTopWidth: 1, borderTopColor: T.line2 }}>
      <Text style={{ fontSize: 14, color: T.ter, lineHeight: 20 }}>{children}</Text>
    </View>
  );
}

export default function RecipeAddScreen() {
  const router = useRouter();
  const { id } = useLocalSearchParams<{ id?: string }>();

  const detail = useRecipeDetail(id);
  const lists = useSettingsLists();
  const save = useSaveRecipe();

  const draft = useRecipeDraft((s) => s.draft);
  const reset = useRecipeDraft((s) => s.reset);
  const patch = useRecipeDraft((s) => s.patch);
  const updateLine = useRecipeDraft((s) => s.updateLine);
  const removeLine = useRecipeDraft((s) => s.removeLine);
  const updateExtra = useRecipeDraft((s) => s.updateExtra);
  const addTaxItem = useRecipeDraft((s) => s.addTaxItem);
  const updateTaxItem = useRecipeDraft((s) => s.updateTaxItem);
  const removeTaxItem = useRecipeDraft((s) => s.removeTaxItem);
  const removeExtra = useRecipeDraft((s) => s.removeExtra);

  const [info, setInfo] = useState<'sales' | 'target' | null>(null);
  const [costMode, setCostMode] = useState<'batch' | 'one'>('one');
  const [plMode, setPlMode] = useState<'batch' | 'one' | 'month'>('one');
  const [catOpen, setCatOpen] = useState(false);
  const settings = useStoreSettings();   // 세금은 매장이 정한다(0087)
  const [qtyEdit, setQtyEdit] = useState<number | null>(null);
  const [qtyDraft, setQtyDraft] = useState('');

  // 진입 시 초안 준비. 수정이면 서버 값으로, 추가면 빈 값으로 한 번만 채운다.
  const d = detail.data;
  useEffect(() => {
    if (id) {
      if (!d || draft.loaded === true && draft.id === id) return;
      reset({
        id: d.id,
        name: d.name,
        categoryId: d.categoryId,
        categoryName: '',
        price: String(d.price),
        memo: d.memo ?? '',
        taxMode: d.taxMode,
        taxItems: d.taxItems.map((t) => ({ name: t.name, rate: String(t.rate) })),
        baseServings: String(d.baseServings),
        avgMonthlySales: d.avgMonthlySales === null ? '' : String(d.avgMonthlySales),
        targetProfitRate: String(d.targetProfitRate),
        lines: d.lines.map((l) => ({
          ingredientId: l.ingredientId,
          subRecipeId: l.subRecipeId,
          name: l.name,
          unit: l.baseUnit === null ? null : l.baseUnit === 'ea' ? '개' : l.baseUnit,
          inputQty: l.inputQty,
          unitPrice: l.unitPrice,
        })),
        extras: d.extras.map((e) => ({ materialId: e.materialId, name: e.name, amount: e.amount, qty: e.qty })),
        loaded: true,
      });
    } else if (draft.loaded === false && draft.id !== undefined) {
      reset(emptyDraft());
    } else if (draft.id !== undefined) {
      // 수정하다 '추가'로 들어온 경우 — 남은 초안을 비운다.
      reset(emptyDraft());
    }
  }, [id, d, draft.loaded, draft.id, reset]);

  const catLabel = useMemo(() => {
    if (draft.categoryName) return draft.categoryName;
    return lists.data?.recipeCategories.find((c) => c.id === draft.categoryId)?.name ?? '';
  }, [draft.categoryName, draft.categoryId, lists.data]);

  const servings = Math.max(1, Math.round(num(draft.baseServings) || 1));
  const price = num(draft.price);
  const target = num(draft.targetProfitRate) / 100;
  const monthly = num(draft.avgMonthlySales);

  /** 1인분 재료비 — 단가가 없는 줄은 0 이 아니라 **계산 불가**로 다룬다. */
  const lineCost = (l: DraftLine) => (l.unitPrice === null ? null : (l.inputQty / servings) * l.unitPrice);
  const material = draft.lines.reduce((s, l) => s + (lineCost(l) ?? 0), 0);
  const unknownLines = draft.lines.filter((l) => l.unitPrice === null).length;
  const extra = draft.extras.reduce((s, e) => s + e.amount * e.qty, 0);
  const fixedRate = d?.fixedRate ?? 0;
  /** 요율이 숫자로 읽히는 항목만 계산에 넣는다 — 서버 `tax_of()` 의 `where rate > 0` 과 같다. */
  /*
   * ⚠ 세금은 **매장 설정**에서 읽는다(0087). 초안에 담아 두면 새 메뉴에서 0원으로
   *   보이다가 저장 후 서버가 매장 값을 얹어 숫자가 달라진다.
   *   고치는 곳은 MY > 세금 한 곳뿐이다.
   */
  const taxItems = settings.data?.taxItems ?? [];
  const tax = round(taxAmount(price, taxItems));
  const fixed = round(fixedRate * price);
  const profit = price - tax - material - fixed - extra;
  const profitRate = price > 0 ? profit / price : 0;
  const warn = profitRate < target;
  const PROFIT = warn ? T.red : T.green;
  // 권장가 분모에도 세금 항목이 들어간다 — 빼면 카드 수수료만큼 낮게 나온다.
  const recRaw = recommendedPrice(material + extra, fixedRate, target, taxRate(taxItems));
  const recommended = recRaw == null ? null : Math.round(recRaw / 100) * 100;

  const cm = costMode === 'batch' ? servings : 1;
  const m = plMode === 'batch' ? servings : plMode === 'month' ? monthly : 1;
  const wm = (v: number) => `${won(Math.round(v * m))}원`;
  const p = (v: number) => (price > 0 ? formatPercent(v / price) : '0.0%');

  const nameError = draft.name.trim() === '' ? '메뉴 이름을 입력해 주세요' : undefined;
  const priceError = price < 0 ? '판매가는 0 이상이어야 해요' : undefined;
  const canSave = !nameError && !priceError && servings >= 1 && !save.isPending;

  const onSave = () => {
    if (!canSave) return;
    save.mutate(
      {
        id: draft.id,
        name: draft.name.trim(),
        price,
        memo: draft.memo.trim() || null,
        baseServings: servings,
        targetProfitRate: num(draft.targetProfitRate),
        avgMonthlySales: draft.avgMonthlySales.trim() === '' ? null : monthly,
        categoryId: draft.categoryId,
        lines: draft.lines.map((l) => ({
          ingredientId: l.ingredientId,
          subRecipeId: l.subRecipeId,
          inputQty: l.inputQty,
        })),
        extras: draft.extras.map((e) => ({
          materialId: e.materialId,
          name: e.name,
          amount: e.amount,
          qty: e.qty,
        })),
      },
      {
        onSuccess: (savedId) => {
          reset(emptyDraft());
          if (draft.id) safeBack(`/recipes/${savedId}`);
          else router.replace(`/recipes/${savedId}` as Href);
        },
        onError: (e) => Alert.alert('저장하지 못했어요', e instanceof Error ? e.message : '잠시 후 다시 시도해 주세요'),
      },
    );
  };

  const openQty = (i: number) => {
    setQtyEdit(i);
    setQtyDraft(String(draft.lines[i]?.inputQty ?? 0));
  };
  const applyQty = () => {
    if (qtyEdit === null) return;
    updateLine(qtyEdit, { inputQty: Math.max(0, num(qtyDraft)) });
    setQtyEdit(null);
  };

  return (
    <View style={{ flex: 1, backgroundColor: T.bg }}>
      <AppHeader title={id ? '레시피 수정' : '레시피 추가'} onBack={() => safeBack('/recipes')} />

      <QueryState
        isLoading={Boolean(id) && detail.isLoading}
        error={detail.error}
        isEmpty={Boolean(id) && detail.isFetched && !d}
        onRetry={() => void detail.refetch()}
        emptyTitle="메뉴를 찾을 수 없어요"
      >
        <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 4, paddingBottom: 24 }}>
          {/* 기본 정보 */}
          <View style={{ marginBottom: 14 }}>
            <Field label="메뉴명" req error={draft.name !== '' ? nameError : undefined}>
              <Input value={draft.name} onChangeText={(t) => patch({ name: t })} placeholder="예) 제육볶음" error={draft.name !== '' && Boolean(nameError)} accessibilityLabel="메뉴명" />
            </Field>
            <Field label="카테고리">
              <Select value={catLabel} placeholder="카테고리 선택" onPress={() => setCatOpen(true)} />
            </Field>
            {/* 메모 — 식재료와 같은 성격이다. 매출 계산에는 안 들어간다(0063). */}
            <Field label="메모" hint="이 메뉴에 대해 기억할 것">
              <Input
                value={draft.memo}
                onChangeText={(t) => patch({ memo: t })}
                placeholder="예) 점심에만 판매"
                accessibilityLabel="메모"
              />
            </Field>
            <View style={{ flexDirection: 'row', gap: 10 }}>
              <View style={{ flex: 1.4 }}>
                <Field label="판매가" req error={draft.price !== '' ? priceError : undefined}>
                  <Input value={draft.price} onChangeText={(t) => patch({ price: clampDecimals(t, 0) })} placeholder="0" suffix="원" mono keyboardType="number-pad" accessibilityLabel="판매가" />
                </Field>
              </View>
            </View>
            <View style={{ flexDirection: 'row', gap: 10 }}>
              <View style={{ flex: 1 }}>
                <Field label="월 평균 판매량" right={<InfoBtn active={info === 'sales'} onPress={() => setInfo((v) => (v === 'sales' ? null : 'sales'))} />}>
                  <Input value={draft.avgMonthlySales} onChangeText={(t) => patch({ avgMonthlySales: clampDecimals(t, 0) })} placeholder="0" suffix="개" mono keyboardType="number-pad" accessibilityLabel="월 평균 판매량" />
                </Field>
              </View>
              <View style={{ flex: 1 }}>
                <Field label="기준 인분" req hint="한 번에 만드는 양">
                  <Input value={draft.baseServings} onChangeText={(t) => patch({ baseServings: clampDecimals(t, 0) })} placeholder="10" suffix="인분" mono keyboardType="number-pad" accessibilityLabel="기준 인분" />
                </Field>
              </View>
            </View>
            <Field label="목표 순이익률" right={<InfoBtn active={info === 'target'} onPress={() => setInfo((v) => (v === 'target' ? null : 'target'))} />}>
              <Input value={draft.targetProfitRate} onChangeText={(t) => patch({ targetProfitRate: clampDecimals(t, 1) })} placeholder="40" suffix="%" mono keyboardType="decimal-pad" accessibilityLabel="목표 순이익률" />
            </Field>
          </View>

          {info ? (
            <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 6, marginTop: -8, marginBottom: 18, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: T.blueTint, borderRadius: 10 }}>
              <Icon name="info" size={15} color={T.blue} />
              <Text style={{ flex: 1, fontSize: 14, color: T.sub, fontWeight: '600', lineHeight: 21 }}>
                {info === 'sales'
                  ? '한 달 평균 판매 수량이에요. 손익 미리보기의 ‘월평균 기준’ 계산에 쓰여요.'
                  : '이 메뉴에서 남기고 싶은 순이익 비율이에요. 현재 순이익률이 목표보다 낮으면 권장 판매가를 알려드려요.'}
              </Text>
            </View>
          ) : null}

          {/* 재료 */}
          <Card pad={0} style={{ overflow: 'hidden' }}>
            <SecHead title="재료" sub={`${draft.lines.length}개`} />
            <View style={{ flexDirection: 'row', gap: 22, paddingHorizontal: 15, backgroundColor: T.surface, borderBottomWidth: 1, borderBottomColor: T.line }}>
              {([['batch', `${servings}인분 기준`], ['one', '1인분 기준']] as const).map(([k, label]) => {
                const on = costMode === k;
                return (
                  <Pressable key={k} onPress={() => setCostMode(k)} accessibilityRole="tab" accessibilityLabel={label} accessibilityState={{ selected: on }} style={{ paddingTop: 13, paddingBottom: 11 }}>
                    <Text style={{ fontSize: 16, fontWeight: on ? '700' : '600', color: on ? T.ink : T.ter }}>{label}</Text>
                    {on ? <View style={{ position: 'absolute', left: 0, right: 0, bottom: 0, height: 2.5, backgroundColor: T.ink, borderRadius: 2 }} /> : null}
                  </Pressable>
                );
              })}
            </View>
            <View style={{ paddingHorizontal: 15, paddingTop: 4, paddingBottom: 15 }}>
              {draft.lines.length === 0 ? (
                <Text style={{ fontSize: 16, color: T.ter, paddingVertical: 14 }}>아래 ‘재료 검색’으로 재료를 담아 주세요</Text>
              ) : (
                draft.lines.map((l, i) => {
                  const cost = lineCost(l);
                  return (
                    <View key={`${l.ingredientId ?? l.subRecipeId}-${i}`} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: T.line2 }}>
                      <Pressable onPress={() => openQty(i)} accessibilityRole="button" accessibilityLabel={`${l.name} 사용량 수정`} style={{ flex: 1, minWidth: 0 }}>
                        <Text style={{ fontSize: 16, fontWeight: '700', color: T.ink }} numberOfLines={1}>
                          {l.name}
                        </Text>
                        <Text style={[{ fontSize: 14, color: T.ter, marginTop: 2 }, NUM]}>
                          {l.unitPrice === null ? '단가 산출 전' : l.unit === null ? `${won(Math.round(l.unitPrice))}원/인분` : formatUnitPrice(l.unitPrice, l.unit)}
                        </Text>
                      </Pressable>
                      <Pressable onPress={() => openQty(i)} accessibilityRole="button" accessibilityLabel={`${l.name} 사용량`} style={{ alignItems: 'flex-end', marginRight: 8 }}>
                        <Text style={[{ fontSize: 16, fontWeight: '800', color: cost === null ? T.ter : T.ink }, NUM]}>
                          {cost === null ? '—' : `${won(Math.round(cost * cm))}원`}
                        </Text>
                        <Text style={[{ fontSize: 14, color: T.blue, marginTop: 1, fontWeight: '700' }, NUM]}>
                          {l.unit === null ? `${(l.inputQty / servings) * cm}인분` : formatQuantity((l.inputQty / servings) * cm, l.unit)}
                        </Text>
                      </Pressable>
                      <Pressable onPress={() => removeLine(i)} hitSlop={8} accessibilityRole="button" accessibilityLabel={`${l.name} 삭제`}>
                        <Icon name="close" size={18} color={T.ter} />
                      </Pressable>
                    </View>
                  );
                })
              )}
              <Pressable
                onPress={() => router.push(`/recipes/ingredient-search${draft.id ? `?exclude=${draft.id}` : ''}` as Href)}
                accessibilityRole="button" accessibilityLabel="재료 검색"
                style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, marginTop: 12, paddingVertical: 13, borderRadius: 12, borderWidth: 1, borderColor: T.blue, backgroundColor: T.blueTint }}
              >
                <Icon name="search" size={17} color={T.blue} sw={2.1} />
                <Text style={{ fontSize: 16, fontWeight: '700', color: T.blue }}>재료 검색</Text>
              </Pressable>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 12, paddingTop: 12, borderTopWidth: 1, borderTopColor: T.line }}>
                <Text style={{ flex: 1, fontSize: 16, fontWeight: '800', color: T.ink2 }}>재료비 소계</Text>
                <View style={{ alignItems: 'flex-end' }}>
                  <Text style={[{ fontSize: 16, fontWeight: '800', color: T.ink }, NUM]}>{won(Math.round(material * cm))}원</Text>
                  <Text style={[{ fontSize: 14, fontWeight: '700', color: T.sub2, marginTop: 2 }, NUM]}>{p(material)}</Text>
                </View>
              </View>
              {unknownLines > 0 ? (
                <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 6, marginTop: 10, paddingVertical: 10, paddingHorizontal: 12, borderRadius: 10, backgroundColor: T.amberTint }}>
                  <Icon name="info" size={15} color={T.amberText} />
                  <Text style={{ flex: 1, fontSize: 14, color: T.amberText, lineHeight: 20 }}>
                    단가가 없는 재료 {unknownLines}개는 원가에서 빠져 있어요. 재고 추가나 입고를 등록하면 원가에 들어가요.
                  </Text>
                </View>
              ) : null}
            </View>
            <Footer>식재료는 검색해서만 담을 수 있어요(단가 자동 연동). 사용량은 기준 인분 전체 양이에요.</Footer>
          </Card>

          <View style={{ height: 9 }} />

          {/* 부자재 */}
          <Card pad={0} style={{ overflow: 'hidden' }}>
            <SecHead title="부자재" sub="(이 메뉴에만 들어가는 부가 원가)" />
            <View style={{ paddingHorizontal: 15, paddingTop: 4, paddingBottom: 15 }}>
              {draft.extras.length === 0 ? (
                <Text style={{ fontSize: 16, color: T.ter, paddingVertical: 14 }}>등록된 부자재가 없어요</Text>
              ) : (
                draft.extras.map((e, i) => (
                  <View key={`${e.materialId ?? e.name}-${i}`} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: T.line2 }}>
                    <View style={{ flex: 1, minWidth: 0 }}>
                      <Text style={{ fontSize: 16, fontWeight: '700', color: T.ink }} numberOfLines={1}>{e.name}</Text>
                      <Text style={[{ fontSize: 14, color: T.ter, marginTop: 2 }, NUM]}>{won(e.amount)}원 × {e.qty}</Text>
                    </View>
                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                      <Pressable onPress={() => updateExtra(i, { qty: Math.max(0, e.qty - 1) })} hitSlop={6} accessibilityRole="button" accessibilityLabel={`${e.name} 수량 줄이기`} style={{ width: 30, height: 30, borderRadius: 8, backgroundColor: T.line2, alignItems: 'center', justifyContent: 'center' }}>
                        <Icon name="minus" size={16} color={T.sub} sw={2.4} />
                      </Pressable>
                      <Text style={[{ minWidth: 22, textAlign: 'center', fontSize: 16, fontWeight: '800', color: T.ink }, NUM]}>{e.qty}</Text>
                      <Pressable onPress={() => updateExtra(i, { qty: e.qty + 1 })} hitSlop={6} accessibilityRole="button" accessibilityLabel={`${e.name} 수량 늘리기`} style={{ width: 30, height: 30, borderRadius: 8, backgroundColor: T.blue, alignItems: 'center', justifyContent: 'center' }}>
                        <Icon name="plus" size={16} color={T.onColor} sw={2.4} />
                      </Pressable>
                    </View>
                    <Pressable onPress={() => removeExtra(i)} hitSlop={8} accessibilityRole="button" accessibilityLabel={`${e.name} 삭제`}>
                      <Icon name="close" size={18} color={T.ter} />
                    </Pressable>
                  </View>
                ))
              )}
              <Pressable
                onPress={() => router.push('/recipes/material-search' as Href)}
                accessibilityRole="button" accessibilityLabel="부자재 검색"
                style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, marginTop: 12, paddingVertical: 13, borderRadius: 12, borderWidth: 1, borderColor: T.blue, backgroundColor: T.blueTint }}
              >
                <Icon name="search" size={17} color={T.blue} sw={2.1} />
                <Text style={{ fontSize: 16, fontWeight: '700', color: T.blue }}>부자재 검색</Text>
              </Pressable>
            </View>
            <Footer>부자재 단가는 마스터에서 관리돼요. 단가를 고치면 이 메뉴 원가도 함께 바뀌어요.</Footer>
          </Card>

          <View style={{ height: 9 }} />

          {/* 손익 미리보기 */}
          <Card onLine pad={0} style={{ overflow: 'hidden' }}>
            <SecHead title="손익 미리보기" sub="판매가 대비 %" />
            <View style={{ flexDirection: 'row', gap: 22, paddingHorizontal: 15, backgroundColor: T.surface, borderBottomWidth: 1, borderBottomColor: T.line }}>
              {([['batch', `${servings}인분`], ['one', '1인분'], ['month', '월평균']] as const).map(([k, label]) => {
                const on = plMode === k;
                const disabled = k === 'month' && monthly <= 0;
                return (
                  <Pressable key={k} onPress={() => setPlMode(k)} disabled={disabled} accessibilityRole="tab" accessibilityLabel={`${label} 기준`} accessibilityState={{ selected: on, disabled }} style={{ paddingTop: 13, paddingBottom: 11, opacity: disabled ? 0.4 : 1 }}>
                    <Text style={{ fontSize: 16, fontWeight: on ? '700' : '600', color: on ? T.ink : T.ter }}>{label} 기준</Text>
                    {on ? <View style={{ position: 'absolute', left: 0, right: 0, bottom: 0, height: 2.5, backgroundColor: T.ink, borderRadius: 2 }} /> : null}
                  </Pressable>
                );
              })}
            </View>
            <View style={{ paddingHorizontal: 15, paddingTop: 4, paddingBottom: 15 }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: T.line }}>
                <Text style={{ flex: 1, fontSize: 16, fontWeight: '800', color: T.ink }}>판매가</Text>
                <View style={{ alignItems: 'flex-end' }}>
                  <Text style={[{ fontSize: 16, fontWeight: '800', color: T.ink }, NUM]}>{wm(price)}</Text>
                  <Text style={[{ fontSize: 14, fontWeight: '600', color: T.ter, marginTop: 2 }, NUM]}>100%</Text>
                </View>
              </View>
              {[
                ...(tax > 0 ? [{ label: '세금', amt: tax }] : []),
                { label: '재료 원가', amt: material },
                { label: '고정 지출', amt: fixed },
                ...(extra > 0 ? [{ label: '부자재', amt: extra }] : []),
              ].map((c) => (
                <View key={c.label} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 9, borderBottomWidth: 1, borderBottomColor: T.line2 }}>
                  <Text style={{ flex: 1, fontSize: 16, fontWeight: '600', color: T.sub }}>
                    <Text style={{ color: T.ter }}>(−) </Text>{c.label}
                  </Text>
                  <View style={{ alignItems: 'flex-end' }}>
                    <Text style={[{ fontSize: 16, fontWeight: '700', color: T.ter }, NUM]}>{wm(c.amt)}</Text>
                    <Text style={[{ fontSize: 14, fontWeight: '600', color: T.ter, marginTop: 2 }, NUM]}>{p(c.amt)}</Text>
                  </View>
                </View>
              ))}
              <View style={{ flexDirection: 'row', alignItems: 'center', paddingTop: 12 }}>
                <Text style={{ fontSize: 16, fontWeight: '800', color: T.ink }}>순이익</Text>
                <View style={{ marginLeft: 7 }}>{warn ? <Badge tone="red" sm solid>목표 미달</Badge> : <Badge tone="green" sm solid>목표 달성</Badge>}</View>
                <View style={{ flex: 1 }} />
                <View style={{ alignItems: 'flex-end' }}>
                  <Text style={[{ fontSize: 16, fontWeight: '800', color: PROFIT }, NUM]}>{wm(profit)}</Text>
                  <Text style={[{ fontSize: 14, fontWeight: '800', color: PROFIT, marginTop: 2 }, NUM]}>{formatPercent(profitRate)}</Text>
                </View>
              </View>
              {warn && recommended != null ? (
                <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 11, paddingTop: 11, borderTopWidth: 1, borderTopColor: T.line }}>
                  <View style={{ flex: 1 }}>
                    <Text style={{ fontSize: 16, fontWeight: '700', color: T.ink2 }}>권장 판매가</Text>
                    <Text style={{ fontSize: 14, color: T.ter, marginTop: 1 }}>목표 {draft.targetProfitRate}% 기준</Text>
                  </View>
                  <Pressable onPress={() => patch({ price: String(recommended) })} accessibilityRole="button" accessibilityLabel="권장 판매가 적용" style={{ alignItems: 'flex-end' }}>
                    <Text style={[{ fontSize: 16, fontWeight: '800', color: T.blue }, NUM]}>{won(recommended)}원</Text>
                    <Text style={{ fontSize: 14, fontWeight: '700', color: T.blue, marginTop: 2 }}>적용하기</Text>
                  </Pressable>
                </View>
              ) : null}
              {!id ? (
                <Text style={{ fontSize: 14, color: T.ter, lineHeight: 20, marginTop: 12 }}>
                  고정지출률은 저장 후 이번 달 값으로 반영돼요.
                </Text>
              ) : null}
            </View>
          </Card>
        </ScrollView>
      </QueryState>

      <View style={{ paddingHorizontal: 20, paddingTop: 12, paddingBottom: 30, backgroundColor: T.surface, borderTopWidth: 1, borderTopColor: T.line2 }}>
        <Button kind="primary" size="lg" full disabled={!canSave} loading={save.isPending} onPress={onSave}>
          {id ? '저장' : '추가'}
        </Button>
      </View>

      {/* 카테고리 */}
      <Sheet visible={catOpen} onClose={() => setCatOpen(false)} title="카테고리 선택" height={520}>
        <ScrollView contentContainerStyle={{ gap: 8, paddingBottom: 20 }} showsVerticalScrollIndicator={false}>
          <Pressable
            onPress={() => { patch({ categoryId: null, categoryName: '' }); setCatOpen(false); }}
            accessibilityRole="button" accessibilityLabel="지정 안 함"
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 14, paddingHorizontal: 16, borderRadius: 12, borderWidth: 1, borderColor: draft.categoryId === null ? T.blue : T.line, backgroundColor: draft.categoryId === null ? T.blueTint : T.surface }}
          >
            <Text style={{ flex: 1, fontSize: 16, fontWeight: '700', color: draft.categoryId === null ? T.blue : T.ter }}>지정 안 함</Text>
            {draft.categoryId === null ? <Icon name="check" size={17} color={T.blue} sw={2.4} /> : null}
          </Pressable>
          {(lists.data?.recipeCategories ?? []).map((c) => {
            const on = draft.categoryId === c.id;
            return (
              <Pressable
                key={c.id}
                onPress={() => { patch({ categoryId: c.id, categoryName: c.name }); setCatOpen(false); }}
                accessibilityRole="button" accessibilityLabel={c.name} accessibilityState={{ selected: on }}
                style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 14, paddingHorizontal: 16, borderRadius: 12, borderWidth: 1, borderColor: on ? T.blue : T.line, backgroundColor: on ? T.blueTint : T.surface }}
              >
                <Text style={{ flex: 1, fontSize: 16, fontWeight: '700', color: on ? T.blue : T.ink2 }}>{c.name}</Text>
                {on ? <Icon name="check" size={17} color={T.blue} sw={2.4} /> : null}
              </Pressable>
            );
          })}
          <Pressable
            onPress={() => { setCatOpen(false); router.push('/recipes/category' as Href); }}
            accessibilityRole="button" accessibilityLabel="카테고리 관리"
            style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 5, paddingVertical: 14, borderRadius: 12, borderWidth: 1, borderStyle: 'dashed', borderColor: T.blue }}
          >
            <Icon name="plus" size={17} color={T.blue} sw={2.2} />
            <Text style={{ fontSize: 16, fontWeight: '700', color: T.blue }}>카테고리 관리</Text>
          </Pressable>
        </ScrollView>
      </Sheet>

      {/* 사용량 수정 */}
      <Sheet
        visible={qtyEdit !== null}
        onClose={() => setQtyEdit(null)}
        title="사용량 수정"
        sub={qtyEdit !== null ? `${draft.lines[qtyEdit]?.name} · ${servings}인분 전체 양` : undefined}
        height={340}
      >
        {qtyEdit !== null ? (
          <View>
            <Field label={`${servings}인분 사용량`} req hint="1인분 양이 아니라 한 번에 만드는 전체 양이에요">
              <Input
                value={qtyDraft}
                onChangeText={(t) => setQtyDraft(clampDecimals(t, 2))}
                suffix={draft.lines[qtyEdit]?.unit ?? '인분'}
                mono
                keyboardType="decimal-pad"
                accessibilityLabel="사용량"
              />
            </Field>
            <Text style={[{ fontSize: 14, color: T.sub2, marginTop: -8, marginBottom: 12 }, NUM]}>
              1인분 {draft.lines[qtyEdit]?.unit === null
                ? `${num(qtyDraft) / servings}인분`
                : formatQuantity(num(qtyDraft) / servings, draft.lines[qtyEdit]?.unit ?? 'g')}
            </Text>
            <View style={{ flexDirection: 'row', gap: 9 }}>
              <View style={{ flex: 1 }}><Button kind="ghost" size="lg" full onPress={() => setQtyEdit(null)}>취소</Button></View>
              <View style={{ flex: 2 }}><Button kind="primary" size="lg" full onPress={applyQty}>적용</Button></View>
            </View>
          </View>
        ) : null}
      </Sheet>
    </View>
  );
}

/**
 * RCP-01 레시피 리스트 — 메뉴별 손익 한눈에.
 *
 * 카드의 순이익·원가율은 **서버가 낸 값**이다(recipe_list). 앱이 다시 계산하면
 * 매출 화면의 숫자와 어긋난다 — 같은 메뉴가 화면마다 다른 이익률로 보이게 된다.
 */
import { useMemo, useState } from 'react';
import { Pressable, ScrollView, Text, View } from 'react-native';
import { type Href, useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Badge, Card, Chip, FAB, Icon, QueryState, ScrollTabs, SearchBar, Sheet } from '@/components/kit';
import { T, won } from '@/theme/tokens';
import { formatPercent } from '@margincook/core';
import { useSettingsLists } from '@/features/master-data/hooks';
import { useRecipeList, type RecipeRow } from '../hooks';

const NUM = { fontVariant: ['tabular-nums' as const] };

/** 검색어 매칭 — 메뉴명·카테고리. 공백은 무시해 "제육 볶음"도 찾히게 한다. */
const squash = (s: string) => s.replace(/\s+/g, '').toLowerCase();
function matchesQuery(r: RecipeRow, q: string): boolean {
  const n = squash(q);
  if (n === '') return true;
  return squash(r.name).includes(n) || squash(r.categoryName ?? '').includes(n);
}

type SortKey = 'rateLow' | 'rateHigh' | 'priceHigh' | 'priceLow' | 'salesHigh';
const SORTS: { key: SortKey; label: string }[] = [
  { key: 'rateLow', label: '순이익률 낮은순' },
  { key: 'rateHigh', label: '순이익률 높은순' },
  { key: 'salesHigh', label: '판매량 많은순' },
  { key: 'priceHigh', label: '판매가 높은순' },
  { key: 'priceLow', label: '판매가 낮은순' },
];

type StatusKey = 'all' | 'selling' | 'stopped';
const STATUS_OPTS: { key: StatusKey; label: string }[] = [
  { key: 'all', label: '전체' },
  { key: 'selling', label: '판매중' },
  { key: 'stopped', label: '판매중지' },
];

type TargetKey = 'all' | 'below' | 'met';
const TARGET_OPTS: { key: TargetKey; label: string }[] = [
  { key: 'all', label: '전체' },
  { key: 'below', label: '목표 미달' },
  { key: 'met', label: '목표 달성' },
];

/** 목표 달성 여부 — 목표는 %(0~100), 실제는 비율(0~1)이라 맞춰서 비교한다. */
const belowTarget = (r: RecipeRow) => r.profitRate * 100 < r.targetProfitRate;

function RecipeCard({ r, onPress }: { r: RecipeRow; onPress: () => void }) {
  const stopped = !r.active;
  // 재료가 바닥나 지금은 못 만드는 메뉴. 판매중지와 달리 입고하면 저절로 풀린다.
  const short = !stopped && r.blockedBy !== null;
  const warn = !stopped && belowTarget(r);
  const rateColor = warn ? T.red : T.green;

  return (
    <Pressable onPress={onPress} accessibilityRole="button" accessibilityLabel={`${r.name} 상세`}>
      <Card pad={0} style={{ overflow: 'hidden', opacity: stopped || short ? 0.55 : 1 }}>
        <View style={{ paddingVertical: 15, paddingHorizontal: 16 }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 7, marginBottom: 12 }}>
            {stopped ? null : warn ? <Badge tone="red" solid sm>목표 미달</Badge> : <Badge tone="green" solid sm>목표 달성</Badge>}
            <Text style={{ flex: 1, fontSize: 16, fontWeight: '800', letterSpacing: -0.3, color: T.ink }} numberOfLines={1}>{r.name}</Text>
            {stopped ? <Badge tone="neutral" sm>판매중지</Badge> : null}
            {short ? <Badge tone="red" sm>재료 부족</Badge> : null}
            {r.categoryName ? <Badge tone="neutral" sm>{r.categoryName}</Badge> : null}
          </View>

          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 9 }}>
            <Text style={{ flex: 1, fontSize: 14, fontWeight: '700', color: T.sub }}>판매가</Text>
            <Text style={[{ fontSize: 14, fontWeight: '800', color: T.ink }, NUM]}>{won(r.price)}원</Text>
          </View>

          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 9 }}>
            <Text style={{ fontSize: 14, fontWeight: '700', color: T.sub }}>순이익</Text>
            {!stopped ? (
              <View style={{ marginLeft: 6, paddingVertical: 2, paddingHorizontal: 7, borderRadius: 6, backgroundColor: T.line2 }}>
                <Text style={[{ fontSize: 14, fontWeight: '700', color: T.sub }, NUM]}>목표 {r.targetProfitRate}%</Text>
              </View>
            ) : null}
            <View style={{ flex: 1 }} />
            <Text style={[{ fontSize: 14, fontWeight: '800', color: rateColor, marginRight: 8 }, NUM]}>{formatPercent(r.profitRate)}</Text>
            <Text style={[{ fontSize: 14, fontWeight: '800', color: T.ink }, NUM]}>{won(Math.round(r.profit))}원</Text>
          </View>

          <View style={{ flexDirection: 'row', alignItems: 'center' }}>
            <Text style={{ flex: 1, fontSize: 14, fontWeight: '700', color: T.sub }}>재료비</Text>
            <Text style={[{ fontSize: 14, fontWeight: '700', color: T.sub2, marginRight: 8 }, NUM]}>{formatPercent(r.materialRate)}</Text>
            <Text style={[{ fontSize: 14, fontWeight: '800', color: T.ink }, NUM]}>{won(Math.round(r.materialCost))}원</Text>
          </View>

          {/* 단가가 없는 재료는 원가에서 조용히 빠진다. 숨기면 순이익이 부풀려 보인다. */}
          {r.unknownCostLines > 0 ? (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5, marginTop: 9, paddingVertical: 8, paddingHorizontal: 10, borderRadius: 8, backgroundColor: T.amberTint }}>
              <Icon name="warn" size={14} color={T.amberText} />
              <Text style={{ flex: 1, fontSize: 14, fontWeight: '600', color: T.amberText }}>
                단가 없는 재료 {r.unknownCostLines}개가 원가에서 빠져 있어요
              </Text>
            </View>
          ) : null}
        </View>
      </Card>
    </Pressable>
  );
}

export default function RecipesListScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();

  const recipes = useRecipeList();
  const lists = useSettingsLists();

  const [sort, setSort] = useState<SortKey>('rateLow');
  const [sortOpen, setSortOpen] = useState(false);
  const [statusFilter, setStatusFilter] = useState<StatusKey>('selling');
  const [statusOpen, setStatusOpen] = useState(false);
  const [targetFilter, setTargetFilter] = useState<TargetKey>('all');
  const [targetOpen, setTargetOpen] = useState(false);
  const [cat, setCat] = useState(0);
  const [searching, setSearching] = useState(false);
  const [query, setQuery] = useState('');

  const tabs = useMemo(() => ['전체', ...(lists.data?.recipeCategories.map((c) => c.name) ?? [])], [lists.data]);
  const selCat = tabs[cat] ?? '전체';

  const filtered = useMemo(() => {
    const rows = (recipes.data ?? []).filter((r) => {
      if (cat !== 0 && (r.categoryName ?? '') !== selCat) return false;
      if (statusFilter === 'selling' && !r.active) return false;
      if (statusFilter === 'stopped' && r.active) return false;
      if (targetFilter !== 'all' && belowTarget(r) !== (targetFilter === 'below')) return false;
      if (!matchesQuery(r, query)) return false;
      return true;
    });
    switch (sort) {
      case 'rateHigh': return rows.sort((a, b) => b.profitRate - a.profitRate);
      case 'priceHigh': return rows.sort((a, b) => b.price - a.price);
      case 'priceLow': return rows.sort((a, b) => a.price - b.price);
      case 'salesHigh': return rows.sort((a, b) => (b.avgMonthlySales ?? 0) - (a.avgMonthlySales ?? 0));
      // 기본은 돈 안 되는 메뉴가 위로.
      default: return rows.sort((a, b) => a.profitRate - b.profitRate);
    }
  }, [recipes.data, cat, selCat, statusFilter, targetFilter, query, sort]);

  const sortLabel = SORTS.find((s) => s.key === sort)?.label ?? '순이익률 낮은순';
  const statusLabel = statusFilter === 'all' ? '판매상태' : STATUS_OPTS.find((s) => s.key === statusFilter)!.label;
  const targetLabel = targetFilter === 'all' ? '목표' : TARGET_OPTS.find((s) => s.key === targetFilter)!.label;
  const isSearch = searching && query.trim() !== '';

  return (
    <View style={{ flex: 1, backgroundColor: T.bg }}>
      <View style={{ paddingTop: insets.top, backgroundColor: T.bg }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', paddingLeft: 20, paddingRight: 12, paddingTop: 6, paddingBottom: 12 }}>
          <Text style={{ flex: 1, fontSize: 22, fontWeight: '800', color: T.ink, letterSpacing: -0.6 }}>레시피</Text>
          <Pressable
            onPress={() => setSearching((v) => !v)}
            accessibilityRole="button" accessibilityLabel="검색"
            accessibilityState={{ selected: searching }}
            style={{ width: 40, height: 40, alignItems: 'center', justifyContent: 'center' }}
          >
            <Icon name="search" size={23} color={searching ? T.blue : T.ink2} />
          </Pressable>
          <Pressable
            onPress={() => router.push('/my/notifications' as Href)}
            accessibilityRole="button" accessibilityLabel="알림"
            style={{ width: 40, height: 40, alignItems: 'center', justifyContent: 'center' }}
          >
            <Icon name="bell" size={24} color={T.ink2} />
          </Pressable>
        </View>
        {searching ? (
          <SearchBar value={query} onChange={setQuery} placeholder="메뉴·카테고리 검색" onClose={() => { setSearching(false); setQuery(''); }} />
        ) : null}
      </View>

      <View style={{ borderBottomWidth: 1, borderBottomColor: T.line3 }}>
        <ScrollTabs tabs={tabs} active={cat} onChange={setCat} />
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flexGrow: 0 }} contentContainerStyle={{ gap: 7, paddingHorizontal: 20, paddingVertical: 12 }}>
        <Chip active onPress={() => setSortOpen(true)}>{sortLabel}</Chip>
        <Chip active={statusFilter !== 'all'} onPress={() => setStatusOpen(true)}>{statusLabel}</Chip>
        <Chip active={targetFilter !== 'all'} onPress={() => setTargetOpen(true)}>{targetLabel}</Chip>
      </ScrollView>

      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 104, gap: 10 }}>
        <QueryState
          isLoading={recipes.isLoading}
          error={recipes.error}
          isEmpty={filtered.length === 0}
          onRetry={() => void recipes.refetch()}
          emptyTitle={isSearch ? `'${query.trim()}' 검색 결과가 없어요` : '해당 조건의 메뉴가 없어요'}
          emptyHint={isSearch ? '다른 이름으로 찾아보세요' : '아래 버튼으로 메뉴를 추가해 보세요'}
        >
          {filtered.map((r) => (
            <RecipeCard key={r.id} r={r} onPress={() => router.push(`/recipes/${r.id}` as Href)} />
          ))}
        </QueryState>
      </ScrollView>

      <FAB label="메뉴 추가" onPress={() => router.push('/recipes/add' as Href)} />

      {/* 정렬 */}
      <Sheet visible={sortOpen} onClose={() => setSortOpen(false)} title="정렬" height={420}>
        {SORTS.map((s) => (
          <Pressable
            key={s.key}
            onPress={() => { setSort(s.key); setSortOpen(false); }}
            accessibilityRole="button" accessibilityLabel={s.label}
            accessibilityState={{ selected: sort === s.key }}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15, paddingHorizontal: 4 }}
          >
            <Text style={{ flex: 1, fontSize: 16, fontWeight: '700', color: sort === s.key ? T.blue : T.ink }}>{s.label}</Text>
            {sort === s.key ? <Icon name="check" size={18} color={T.blue} sw={2.4} /> : null}
          </Pressable>
        ))}
      </Sheet>

      {/* 판매 상태 */}
      <Sheet visible={statusOpen} onClose={() => setStatusOpen(false)} title="판매 상태" height={320}>
        {STATUS_OPTS.map((s) => (
          <Pressable
            key={s.key}
            onPress={() => { setStatusFilter(s.key); setStatusOpen(false); }}
            accessibilityRole="button" accessibilityLabel={s.label}
            accessibilityState={{ selected: statusFilter === s.key }}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15, paddingHorizontal: 4 }}
          >
            <Text style={{ flex: 1, fontSize: 16, fontWeight: '700', color: statusFilter === s.key ? T.blue : T.ink }}>{s.label}</Text>
            {statusFilter === s.key ? <Icon name="check" size={18} color={T.blue} sw={2.4} /> : null}
          </Pressable>
        ))}
      </Sheet>

      {/* 목표 달성 여부 */}
      <Sheet visible={targetOpen} onClose={() => setTargetOpen(false)} title="목표 달성" height={320}>
        {TARGET_OPTS.map((s) => (
          <Pressable
            key={s.key}
            onPress={() => { setTargetFilter(s.key); setTargetOpen(false); }}
            accessibilityRole="button" accessibilityLabel={s.label}
            accessibilityState={{ selected: targetFilter === s.key }}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15, paddingHorizontal: 4 }}
          >
            <Text style={{ flex: 1, fontSize: 16, fontWeight: '700', color: targetFilter === s.key ? T.blue : T.ink }}>{s.label}</Text>
            {targetFilter === s.key ? <Icon name="check" size={18} color={T.blue} sw={2.4} /> : null}
          </Pressable>
        ))}
      </Sheet>
    </View>
  );
}

/**
 * SALES-01 매출관리 홈 — 오늘 판매 입력 + 실시간 손익.
 *
 * 여기서 저장하면 서버가 그날 스냅샷의 직접 식재료 라인으로 **식재료 재고까지 차감**한다(E10 → E8).
 * 반제품은 1차 입력이 금지돼 있다.
 * 그래서 저장 버튼은 "매출 기록"이 아니라 "판매 확정"이다. 재고가 모자란 채로 팔렸다면
 * 서버가 부족분을 돌려주고, 화면은 그걸 숨기지 않고 알린다.
 */
import { useMemo, useState } from 'react';
import { Alert, Pressable, ScrollView, Text, View } from 'react-native';
import { type Href, useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Badge, Button, Card, ConfirmSheet, Field, Icon, Input, QueryState, Sheet, SortChip, SortSheet, type SortOption } from '@/components/kit';
import { T, won } from '@/theme/tokens';
import { useRecipeList, type RecipeRow } from '@/features/recipes/hooks';


import { useCheckSaleShortages, useRecipeShortages, useSalesDay, useSaveSale,
  type ChannelCode, type EtcItem, type ExtraItem, type SaleItemInput, type Shortage, type ShortageRecipe } from '../hooks';
import { ShortageWarningSheet } from '../components/ShortageWarningSheet';
import { SaleStepper } from '../components/SaleStepper';
import { BusinessDateGate } from '@/features/business-day/components/BusinessDateGate';
import { setPendingSale, clearPendingSale } from '../pendingSale';
import { CHANNEL_LABEL, channelName } from '../channels';
import { isClosedError, isLateOpenError, isNotOpenError, isRevisionConflict, useBusinessDay, useDayMenuBasis, useSalesBusinessDate } from '@/features/business-day/businessDay';
import { BusinessDayBar } from '../components/BusinessDayBar';
import { LateCloseSheet } from '../components/LateCloseSheet';
import { dayLabel } from '@/lib/date';

const NUM = { fontVariant: ['tabular-nums' as const] };

type SortKey = 'qty' | 'name' | 'profit';
const SORTS: readonly SortOption<SortKey>[] = [
  { key: 'qty', label: '판매량순', hint: '오늘 많이 팔린 메뉴부터' },
  { key: 'profit', label: '순이익순', hint: '개당 순이익이 큰 메뉴부터' },
  { key: 'name', label: '이름순', hint: '가나다순' },
];

/** 화면 입력용 수량 묶음. 저장 전까지는 서버 값과 별개로 들고 있어야 취소가 가능하다. */
interface Qty { hall: number; delivery: number; takeout: number; waste: number }
const ZERO: Qty = { hall: 0, delivery: 0, takeout: 0, waste: 0 };

/**
 * ⚠ **서버가 정한 장부 날짜**를 받고 나서 본체를 붙인다(0125).
 *
 *   앱이 `+09:00` 고정 오프셋으로 오늘을 만들면 앱과 DB 가 각자 오늘을 갖는다
 *   (기획서 §2.1). 새벽 영업이면 장부는 전날인데 앱은 자정에 날짜를 넘겨 버려
 *   그 판매가 다음 날 장부로 샌다.
 *
 *   빈 날짜로 본체를 그리면 안 되는 이유가 하나 더 있다 — 머리글이
 *   `dayLabel('')` 로 **`NaN월 NaN일`** 을 낸다. 실제로 그랬다.
 *   그리고 날짜 조회가 실패했을 때 게이트가 오류와 재시도를 보여 준다.
 */
export default function SalesHomeScreen() {
  return (
    <BusinessDateGate source={useSalesBusinessDate()} title="매출관리">
      {(today) => <SalesHomeBody today={today} />}
    </BusinessDateGate>
  );
}

function SalesHomeBody({ today }: { today: string }) {
  /*
   * ⚠ 자동 마감 실행은 **여기 한 곳**이다(과도기). 예전엔 영업일 조회 훅 안에 있었는데,
   *   날짜 권위를 서버로 옮기면서 그 훅이 날짜 조회의 통로가 됐다 — 그대로 두면
   *   폐기 내역·입고 등록·발주 화면을 **여는 것만으로 영업이 종료된다.**
   *   pg_cron 이 들어오면 이 줄을 지운다.
   */
  const insets = useSafeAreaInsets();
  const router = useRouter();

  const day = useSalesDay(today);
  const recipes = useRecipeList();
  const saveSale = useSaveSale();
  const bday = useBusinessDay();

  const shortage = useRecipeShortages();
  /**
   * 오늘 팔면 얼마로 잡히는지(0061). 카드가 현재 레시피를 보고 있으면
   * 판매가를 고친 순간 화면과 장부가 어긋난다 — 화면이 20,000 이라 해 놓고
   * 12,000 이 기록되는 식이다.
   */
  const basis = useDayMenuBasis(today);

  const [sel, setSel] = useState<RecipeRow | null>(null);
  const [draft, setDraft] = useState<Qty>(ZERO);
  const [sort, setSort] = useState<SortKey>('qty');
  const [sortOpen, setSortOpen] = useState(false);
  /** 판매를 저장하려다 45001 로 막혔을 때, 영업을 시작하면 이어서 다시 저장한다. */
  const [pendingRetry, setPendingRetry] = useState<null | (() => void)>(null);
  /** 늦은 개점(45015) — 고른 시간으로 같은 저장을 다시 민다(0162). */
  const [lateRetry, setLateRetry] = useState<null | ((closeTime: string) => void)>(null);
  /** 짧은 알림 — 팝업 대신. 웹에서도 뜬다. */
  const [toast, setToast] = useState<string | null>(null);
  /**
   * 저장 직전에 잰 부족 결과. 있으면 시트를 띄우고, `그대로 판매` 를 누르면 저장한다.
   * ⚠ 판매는 **한 번만** 저장한다(기획안 §4.5). 경고 때문에 두 번 부르면 안 된다 —
   *   그래서 잴 때는 `sale_shortages`(읽기 전용)만 부르고, 저장은 여기서 한 번 한다.
   */
  const [ask, setAsk] = useState<null | { recipes: ShortageRecipe[]; save: () => void }>(null);
  const checkShortages = useCheckSaleShortages();

  const [etcOpen, setEtcOpen] = useState(false);
  const [etcName, setEtcName] = useState('');
  const [etcPrice, setEtcPrice] = useState('');
  const [etcQty, setEtcQty] = useState('1');
  /*
   * 기본값은 매장이다 — 주류·음료는 거의 매장에서 나간다.
   * ⚠ 기본값이 있다고 '모르면 매장'인 건 아니다. 옛 줄은 channel 이 아예 없고,
   *   그건 미지정으로 남는다(0093).
   */
  const [etcChannel, setEtcChannel] = useState<ChannelCode>('hall');

  const [expOpen, setExpOpen] = useState(false);
  const [expName, setExpName] = useState('');
  const [expAmount, setExpAmount] = useState('');
  const [expMemo, setExpMemo] = useState('');

  const s = day.data;
  const summary = s?.summary;

  /** 메뉴 id → 오늘 저장된 수량. 시트를 열 때 초깃값이 된다. */
  const soldBy = useMemo(() => {
    const m = new Map<string, Qty>();
    for (const it of s?.items ?? []) {
      if (it.recipeId) m.set(it.recipeId, { hall: it.qtyHall, delivery: it.qtyDelivery, takeout: it.qtyTakeout, waste: it.qtyWaste });
    }
    return m;
  }, [s]);

  const basisMap = basis.data;
  const list = useMemo(() => {
    const rows = [...(recipes.data ?? [])];
    switch (sort) {
      case 'name': return rows.sort((a, b) => a.name.localeCompare(b.name, 'ko'));
      // 순이익순도 오늘 기준으로 — 카드에 보이는 값과 정렬 기준이 달라지면 안 된다.
      case 'profit':
        return rows.sort((a, b) =>
          (basisMap?.get(b.id)?.profit ?? b.profit) - (basisMap?.get(a.id)?.profit ?? a.profit));
      default:
        return rows.sort((a, b) => {
          const qa = soldBy.get(a.id);
          const qb = soldBy.get(b.id);
          const ta = qa ? qa.hall + qa.delivery + qa.takeout : 0;
          const tb = qb ? qb.hall + qb.delivery + qb.takeout : 0;
          return tb - ta || a.name.localeCompare(b.name, 'ko');
        });
    }
  }, [recipes.data, sort, soldBy, basisMap]);

  const openMenu = (r: RecipeRow) => {
    setSel(r);
    setDraft(soldBy.get(r.id) ?? ZERO);
  };

  /*
   * 부족분은 오류가 아니다 — 이미 팔린 것이다.
   * ⚠ 0102 이후 부족분은 **음수 재고로 장부에 남는다.** 그래서 긴 목록 팝업 대신
   *   짧게만 알리고, 자세한 건 상단의 `식재료 부족 N개` 안내가 계속 들고 있는다
   *   (기획안 §4.5). 팝업으로 다 말하면 닫는 순간 사라진다.
   */
  const warnShortages = (shortages: Shortage[]) => {
    if (shortages.length === 0) return;
    setToast('판매를 기록했어요 · 부족분은 음수 재고로 반영돼요');
  };

  /*
   * 저장이 막힌 두 경우는 오류가 아니라 **다음에 할 일**이다.
   *  45001 아직 영업 전  → 영업을 시작하고 방금 누른 판매를 이어서 저장한다.
   *  45002 이미 종료됨   → 사실만 알린다. **되돌릴 길은 없다**(기획서 §6.4) —
   *                         과거 판매 수정은 정정 RPC 가 맡을 일이고 아직 없다.
   *
   * ⚠ `Alert.alert()` 은 웹에서 **빈 함수**라 아무 일도 안 일어난다
   *   (`react-native-web` 의 구현이 `static alert() {}`).
   *   여기가 특히 치명적이었다 — 45001 확인창이 안 뜨니 **판매 저장이 영영 막혔다.**
   */
  const onSaveError = (e: unknown, retry: () => void, retryLate?: (closeTime: string) => void) => {
    if (isNotOpenError(e)) { setPendingRetry(() => retry); return; }
    // 45015 — 영업시간이 지난 첫 판매. 오늘 마칠 시간을 골라 열기+저장을 다시 민다(0162).
    if (isLateOpenError(e) && retryLate) { setLateRetry(() => retryLate); return; }
    if (isClosedError(e)) { setToast('영업이 종료되어 판매를 저장할 수 없어요'); return; }
    /*
     * ⚠ 낡은 화면(45009 · 0117). 예전엔 이런 저장이 **그냥 통과했고**, 다른 기기가 적은
     *   판매를 조용히 지웠다(실측: 제육 5개가 사라졌다). 이제 서버가 막는다.
     *   할 일은 하나다 — 다시 받아서 보여 준다. 사장님이 보고 다시 누르면 된다.
     */
    if (isRevisionConflict(e)) {
      /*
       * 낡은 화면이란 **다른 기기가 고치기 전 데이터를 보고 있는 지금 이 화면**이다.
       * 그러니 붙잡을 게 없다 — 들고 있던 데이터도, 입력하던 값도 **버리고** 다시 받는다.
       *
       * ⚠ 초안을 남겨 두면 안 된다. 그대로 다시 누르면 방금 남이 고친 값을
       *   내 낡은 값으로 덮어쓰게 된다. 지금 판본이라 이번엔 서버도 안 막는다.
       * ⚠ 모달로 세우지 않는다. 사장님이 할 일이 없는 알림이다 —
       *   최신 내역은 이미 다시 받고 있다. 짧게만 알린다.
       */
      setSel(null); setDraft(ZERO);
      setEtcOpen(false); setEtcName(''); setEtcPrice(''); setEtcQty('1');
      setExpOpen(false); setExpName(''); setExpAmount(''); setExpMemo('');
      setAsk(null); setPendingRetry(null); clearPendingSale();
      void day.refetch();
      setToast('다른 기기에서 판매 내역이 변경됐어요 · 최신 내역을 다시 불러왔어요');
      return;
    }
    setToast(e instanceof Error ? e.message : '저장하지 못했어요');
  };

  /*
   * 판매 저장 — **재는 것과 저장하는 것을 갈라 둔다.**
   *
   * ⚠ 재고가 모자라도 막지 않는다(기획안 §2.1·§4.4). 예전엔 서버가 막았고,
   *   한 번 음수가 되면 그 메뉴를 **영영 못 고쳤다** — 수량을 되돌리는 것조차
   *   같은 문으로 들어오기 때문이다. 지금은 알리기만 한다.
   *
   * ⚠ 판정은 서버가 한다. 전체 판매량이 아니라 **이번에 더 빠질 몫**이라
   *   10개를 7개로 줄이는 저장에는 경고가 뜨지 않는다.
   */
  /*
   * 재고를 재고 → (모자라면 묻고) → 저장. **재시도도 이 문으로 들어온다.**
   *
   * ⚠ 예전엔 `아직 영업 전`(45001)으로 막힌 뒤 영업을 시작하고 **저장만** 다시 불렀다.
   *   그런데 첫 검사는 스냅샷이 없을 때 이미 `부족 0건` 을 받아 놨다 — 필요량이
   *   그날 스냅샷에서 오기 때문이다(0119 `has_basis`). 그래서 영업 시작 직후
   *   재시도에서는 경고가 통째로 새어 나갔다. 이제 재시도가 검사부터 다시 한다.
   */
  /*
   * ⚠ `openDay` 는 45001 확인을 받은 재시도만 true 다(0154). 서버가 영업 시작과
   *   저장을 **한 트랜잭션**으로 한다 — 예전엔 여기서 open RPC 를 따로 부른 뒤
   *   저장을 다시 불렀고, 열기만 되고 저장이 죽으면 빈 영업일이 남았다.
   *   첫 판매의 부족 경고는 시트 대신 저장 응답의 부족분 알림이 맡는다 —
   *   저장 전에 재려 해도 스냅샷이 아직 없어 못 잰다(0119 hasBasis).
   */
  const checkThenSave = (items: SaleItemInput[], openDay = false, openCloseTime?: string) => {
    // ⚠ 그날 장부를 아직 못 받았으면 저장하지 않는다. 판본을 모르는 채로 보내면
    //   서버가 검사를 건너뛰고, 그 틈으로 낡은 덮어쓰기가 들어온다(0117).
    if (!s) return;
    const run = () =>
      saveSale.mutate(
        // ⚠ 판본을 반드시 실어 보낸다(0117). 빼먹으면 그 경로로 낡은 화면이 남을 덮어쓴다.
        { date: today, items, baseRevision: s.revision, openDay, openCloseTime },
        {
          onSuccess: ({ shortages, dayOpened }) => {
            setSel(null); clearPendingSale();
            if (dayOpened) {
              setToast(shortages.length > 0
                ? '영업을 시작하고 판매를 기록했어요 · 부족분은 음수 재고로 반영돼요'
                : '영업을 시작하고 판매를 기록했어요');
            } else {
              warnShortages(shortages);
            }
          },
          onError: (e) => onSaveError(e, () => checkThenSave(items, true), (t) => checkThenSave(items, true, t)),
        },
      );

    void (async () => {
      let short;
      try {
        short = await checkShortages(today, items);
      } catch {
        // 재는 데 실패했다고 판매를 막지 않는다. 저장은 저장대로 되어야 한다.
        run();
        return;
      }
      /*
       * ⚠ `hasBasis` 가 false 면 `0건` 은 "넉넉하다"가 아니라 **"못 쟀다"** 다(0119).
       *   그대로 저장하면 서버가 45001 로 막고, 영업을 시작한 뒤 이 함수가 다시 불려
       *   그때는 스냅샷이 있으니 제대로 잰다. 여기서 억지로 경고를 띄우지 않는다.
       */
      if (!short.hasBasis || short.ingredientCount === 0) { run(); return; }
      // `재고 확인` 으로 건너갔다가 돌아와도 같은 묶음을 다시 잴 수 있게 들려 보낸다.
      setPendingSale(today, items);
      setAsk({ recipes: short.recipes, save: run });
    })();
  };

  const saveQty = () => {
    if (!sel) return;
    const items: SaleItemInput[] = [...soldBy.entries()]
      .filter(([id]) => id !== sel.id)
      .map(([recipeId, q]) => ({ recipeId, qtyHall: q.hall, qtyDelivery: q.delivery, qtyTakeout: q.takeout, qtyWaste: q.waste }));
    items.push({ recipeId: sel.id, qtyHall: draft.hall, qtyDelivery: draft.delivery, qtyTakeout: draft.takeout, qtyWaste: draft.waste });
    checkThenSave(items);
  };

  const allItems = () =>
    [...soldBy.entries()].map(([recipeId, q]) => ({
      recipeId, qtyHall: q.hall, qtyDelivery: q.delivery, qtyTakeout: q.takeout, qtyWaste: q.waste,
    }));

  const addEtc = () => {
    const price = Number(etcPrice.replace(/[^\d.-]/g, ''));
    const qty = Number(etcQty.replace(/[^\d.-]/g, '')) || 1;
    if (etcName.trim() === '' || !Number.isFinite(price) || price < 0) {
      Alert.alert('입력을 확인해 주세요', '항목명과 판매가를 입력해 주세요.');
      return;
    }
    if (!s) return;   // 판본을 모르면 저장하지 않는다(0117)
    const next: EtcItem[] = [...s.etcItems, { name: etcName.trim(), price, qty, channel: etcChannel }];
    /*
     * ⚠ 기타 매출은 **배열 통째로** 교체된다. 그래서 낡은 화면이 저장하면 다른 기기가
     *   넣은 항목이 통째로 사라진다 — A 가 소주, B 가 맥주를 넣으면 하나만 남는다.
     *   항목 단위로 합치지 않는 이유는 같은 이름이 여럿일 수 있어 무엇이 같은
     *   항목인지 정할 수 없기 때문이다. 대신 **판본 검사**로 낡은 배열을 막는다.
     */
    const run = (openDay = false, openCloseTime?: string) =>
      saveSale.mutate(
        { date: today, items: allItems(), etcItems: next, baseRevision: s.revision, openDay, openCloseTime },
        {
          onSuccess: () => {
            setEtcOpen(false); setEtcName(''); setEtcPrice(''); setEtcQty('1');
            // 채널은 되돌리지 않는다 — 배달 음료를 연달아 적는 게 흔하다.
          },
          // 45001 재시도는 영업 시작을 겸한다(0154) — 한 트랜잭션이다. 45015 는 시간을 골라서(0162).
          onError: (e) => onSaveError(e, () => run(true), (t) => run(true, t)),
        },
      );
    run();
  };

  const addExpense = () => {
    const amount = Number(expAmount.replace(/[^\d.-]/g, ''));
    if (expName.trim() === '' || !Number.isFinite(amount) || amount <= 0) {
      Alert.alert('입력을 확인해 주세요', '항목명과 금액을 입력해 주세요.');
      return;
    }
    if (!s) return;   // 판본을 모르면 저장하지 않는다(0117)
    const next: ExtraItem[] = [...s.extraItems, { name: expName.trim(), amount, memo: expMemo.trim() || undefined }];
    const run = (openDay = false, openCloseTime?: string) =>
      saveSale.mutate(
        { date: today, items: allItems(), extraItems: next, baseRevision: s.revision, openDay, openCloseTime },
        {
          onSuccess: () => { setExpOpen(false); setExpName(''); setExpAmount(''); setExpMemo(''); },
          // 45001 재시도는 영업 시작을 겸한다(0154) — 한 트랜잭션이다. 45015 는 시간을 골라서(0162).
          onError: (e) => onSaveError(e, () => run(true), (t) => run(true, t)),
        },
      );
    run();
  };

  const marginPct = summary && summary.revenue > 0 ? Math.round((summary.profit / summary.revenue) * 1000) / 10 : 0;
  /** 아직 오늘을 시작 안 했나 — 히어로가 0원 대신 `—` 를 보여 줘야 하는 상태. */
  const beforeOpen = bday.data?.status === 'none';
  /*
   * 재고 부족 안내 — 프로토타입 `.stock-notice`.
   * ⚠ 개수는 **서버가 센다**(`recipe_shortages`). 화면에서 다시 세면 재고 확인 화면과
   *   숫자가 갈라진다 — 판정 기준이 두 벌이 되기 때문이다.
   */
  const shortCount = shortage.data?.ingredientCount ?? 0;
  const draftTotal = draft.hall + draft.delivery + draft.takeout;
  const sortLabel = SORTS.find((x) => x.key === sort)?.label ?? '판매량순';

  return (
    <View style={{ flex: 1, backgroundColor: T.bg }}>
      <View style={{ paddingTop: insets.top, backgroundColor: T.bg }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', paddingLeft: 20, paddingRight: 12, paddingTop: 6, paddingBottom: 12 }}>
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: 22, fontWeight: '800', color: T.ink, letterSpacing: -0.6 }}>매출관리</Text>
            <Text style={{ fontSize: 14, color: T.sub2, marginTop: 2, fontWeight: '600' }}>{dayLabel(today, today)}</Text>
          </View>
          <Pressable
            onPress={() => router.push('/sales/analytics' as Href)}
            style={{ width: 40, height: 40, alignItems: 'center', justifyContent: 'center' }}
            accessibilityRole="button" accessibilityLabel="매출 분석"
          >
            <Icon name="calendar" size={23} color={T.ink2} />
          </Pressable>
        </View>
      </View>

      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 24 }}>
        {/*
          재고 부족 안내 — 프로토타입 `.stock-notice`. **맨 위**다.
          부족한 게 없으면 아예 안 그린다(프로토타입도 count===0 이면 빈 문자열).
        */}
        {shortCount > 0 ? (
          <Pressable
            onPress={() => router.push('/sales/stock-check' as Href)}
            accessibilityRole="button"
            accessibilityLabel={`식재료 부족 ${shortCount}개 — 재고 확인`}
            style={{
              flexDirection: 'row', alignItems: 'center', gap: 9, minHeight: 52, marginBottom: 11,
              paddingVertical: 11, paddingHorizontal: 13,
              borderWidth: 1, borderColor: T.red, borderRadius: 13, backgroundColor: T.redTint,
            }}
          >
            <Icon name="warn" size={16} color={T.red} />
            <View style={{ flex: 1, minWidth: 0 }}>
              <Text style={{ fontSize: 13, fontWeight: '800', color: T.red }}>
                식재료 부족 {shortCount}개
              </Text>
              <Text style={{ fontSize: 11, fontWeight: '700', color: T.sub, marginTop: 3 }}>
                부족한 식재료의 재고를 추가해 주세요
              </Text>
            </View>
            <Icon name="chevron" size={16} color={T.red} />
          </Pressable>
        ) : null}

        {/* 영업 상태 — 오늘 기준값이 언제 굳는지 여기서 정해진다 */}
        {bday.data ? <BusinessDayBar state={bday.data} /> : null}

        {/*
          오늘 순이익 — 프로토타입 `.hero`.
          ⚠ 세 칸(매출·지출·이익률)을 **한 줄**로 합쳤다. 프로토타입은
            `매출 529,500원 · 순이익률 17.9%` 한 줄이고, 지출은 아래 일 손익에서 본다.
          ⚠ 영업 전에는 값 자리에 `—` 를 둔다. 0원이라고 쓰면 "오늘 하나도 못 팔았다"로
            읽히는데, 사실은 아직 시작을 안 한 것이다.
          카드 전체를 누르면 일 손익으로 간다 — 프로토타입에 `일 상세` 링크는 없다.
        */}
        <Pressable
          onPress={() => router.push(`/sales/day?date=${today}` as Href)}
          accessibilityRole="button" accessibilityLabel="오늘 손익 자세히"
          style={{ backgroundColor: T.blue, borderRadius: 16, padding: 16, marginBottom: 11 }}
        >
          <Text style={{ fontSize: 13, fontWeight: '700', color: 'rgba(255,255,255,0.82)' }}>오늘 순이익</Text>
          <Text style={[{ fontSize: 25, fontWeight: '800', color: T.onColor, letterSpacing: -0.6, marginTop: 7 }, NUM]}>
            {beforeOpen ? '—' : `${won(summary?.profit ?? 0)}원`}
          </Text>
          <Text style={[{ fontSize: 13, fontWeight: '700', color: 'rgba(255,255,255,0.86)', marginTop: 4 }, NUM]}>
            {beforeOpen
              ? '영업을 시작하면 오늘 기록이 열려요'
              : `매출 ${won(summary?.revenue ?? 0)}원 · 순이익률 ${marginPct}%`}
          </Text>
        </Pressable>

        {/* 기타 매출 · 지출 추가 */}
        <View style={{ flexDirection: 'row', gap: 8, marginBottom: 12 }}>
          {([
            ['기타 매출', s?.etcRevenue ?? 0, () => setEtcOpen(true)],
            ['지출 추가', s?.dailyExtra ?? 0, () => setExpOpen(true)],
          ] as const).map(([label, amt, onP]) => (
            <Pressable
              key={label}
              onPress={onP}
              accessibilityRole="button" accessibilityLabel={label}
              style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 5, paddingVertical: 13, borderRadius: 12, borderWidth: 1, borderColor: T.line, backgroundColor: T.surface }}
            >
              <Icon name="plus" size={16} color={T.sub2} sw={2.2} />
              <Text style={{ fontSize: 14, fontWeight: '700', color: T.sub }}>{label}</Text>
              {amt > 0 ? <Text style={[{ fontSize: 14, fontWeight: '700', color: T.blue }, NUM]}>{won(amt)}</Text> : null}
            </Pressable>
          ))}
        </View>

        {/* 정렬 + 메뉴 관리 */}
        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginHorizontal: 2, marginBottom: 9 }}>
          <SortChip label={sortLabel} onPress={() => setSortOpen(true)} />
          <Pressable
            onPress={() => router.push('/recipes' as Href)}
            accessibilityRole="button" accessibilityLabel="메뉴 관리"
            hitSlop={6}
            style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}
          >
            <Icon name="edit" size={15} color={T.blue} sw={2.2} />
            <Text style={{ fontSize: 14, fontWeight: '700', color: T.blue }}>메뉴 관리</Text>
          </Pressable>
        </View>

        <QueryState
          isLoading={recipes.isLoading || day.isLoading}
          error={recipes.error ?? day.error}
          isEmpty={list.length === 0}
          onRetry={() => { void recipes.refetch(); void day.refetch(); }}
          emptyTitle="등록된 메뉴가 없어요"
          emptyHint="레시피 탭에서 메뉴를 먼저 등록해 주세요"
        >
          <Card pad={0} style={{ overflow: 'hidden' }}>
            {list.map((m, i) => {
              const q = soldBy.get(m.id);
              const total = q ? q.hall + q.delivery + q.takeout : 0;
              const b = basis.data?.get(m.id);
              // 팔 수 없는 이유. 사장님이 끈 것이 먼저다 — 그건 의도이고, 재료는 상태다.
              // ⚠ 오늘 기준에 없는 메뉴는 막지 않는다(0062). 오늘 기록이 없어 움직일 숫자가
              //   없으므로, 팔면 그 시점 값으로 오늘 기준에 더해진다.
              /*
               * ⚠ **판매를 막는 것은 `판매 중지` 하나뿐이다**(기획안 §2.1).
               *   그건 사장님이 끈 것이고 — 의도다.
               *
               *   재료 부족은 막지 않는다. 예전엔 `blockedBy` 도 같이 막았고,
               *   그래서 서버에서 음수 재고를 허용해도 **화면에서 닿을 수가 없었다.**
               *   더 나쁜 건 한 번 음수가 된 메뉴의 수량을 **되돌리지도 못한 것**이다 —
               *   수정도 같은 판매 버튼으로 들어오기 때문이다.
               *   부족은 빨간 뱃지로 알리고, 저장 직전에 한 번 더 묻는다.
               */
              const stopped = !m.active;
              const short = !stopped && m.blockedBy !== null;
              const blocked = stopped;
              return (
                <View key={m.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, minHeight: 82, paddingVertical: 12, paddingHorizontal: 14, borderBottomWidth: i < list.length - 1 ? 1 : 0, borderBottomColor: T.line2, opacity: blocked ? 0.45 : 1 }}>
                  <View style={{ flex: 1, minWidth: 0 }}>
                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                      <Text style={{ fontSize: 15, fontWeight: '800', color: T.ink }} numberOfLines={1}>{m.name}</Text>
                      {stopped ? <Badge tone="neutral" sm>판매 중지</Badge> : short ? <Badge tone="red" sm solid>재료 부족</Badge> : null}
                    </View>
                    <Text style={[{ fontSize: 12, color: T.ter, marginTop: 3 }, NUM]}>
                      {/* 왜 안 되는지 그 자리에서 밝힌다 — 배지만으로는 어느 재료인지 모른다. */}
                      {short
                        ? `${m.blockedBy}이(가) 모자라요 · 팔면 부족분이 음수 재고로 남아요`
                        // ⚠ 오늘 팔면 잡히는 값이다. 현재 레시피가 아니다(0061).
                        : `판매가 ${won(Math.round(b?.price ?? m.price))} · 재료비 ${won(Math.round(b?.materialCost ?? m.materialCost))}`}
                    </Text>
                    {/*
                      지금 값이 오늘 장부와 다르다고 그 자리에서 밝힌다.
                      ⚠ `수정한 값` 이라고 쓰면 안 된다. 이 표시는 **원인을 모른다** —
                        서버의 `changed` 는 `현재 원가 ≠ 스냅샷 원가` 일 뿐이라,
                        사장님이 레시피를 고쳤을 때도 켜지지만 **입고로 단가가 움직여도** 켜진다.
                        실제로 DB 를 새로 깐 직후, 아무것도 안 고쳤는데 네 메뉴에 이 문구가 떠 있었다
                        (그날 보충 입고가 영업 시작 뒤에 들어왔기 때문이다).
                        고치지도 않은 걸 고쳤다고 하면 사장님은 이 줄을 안 믿게 된다.
                      판매가는 사장님만 바꾸므로 그때만 `판매가` 라고 짚어 준다.
                    */}
                    {b?.changed ? (
                      <Text style={[{ fontSize: 13, color: T.amberText, marginTop: 3, fontWeight: '600' }, NUM]}>
                        {b.currentPrice !== b.price
                          ? `판매가 ${won(Math.round(b.currentPrice))}원은 다음 영업일부터 적용돼요`
                          : `지금 재료비 ${won(Math.round(b.currentMaterialCost))}원은 다음 영업일부터 적용돼요`}
                      </Text>
                    ) : null}
                  </View>

                  {/*
                    우측 수량·금액 — 프로토타입 `.menu-value`.
                    ⚠ 좌측에 있던 `총 N개` 줄을 여기로 올렸다. 같은 것을 두 자리에 두지 않는다.
                      누르면 수량 수정으로 가는 것도 그대로다.
                  */}
                  <Pressable
                    onPress={() => openMenu(m)}
                    disabled={blocked}
                    accessibilityRole="button" accessibilityLabel={`${m.name} 판매 수량 수정`}
                    style={{ alignItems: 'flex-end' }}
                    hitSlop={6}
                  >
                    <Text style={[{ fontSize: 15, fontWeight: '800', color: total > 0 ? T.ink : T.ter }, NUM]}>
                      {total}개{q && q.waste > 0 ? ` · 폐기 ${q.waste}` : ''}
                    </Text>
                    {total > 0 ? (
                      <Text style={[{ fontSize: 12, fontWeight: '700', color: T.ter, marginTop: 3 }, NUM]}>
                        {won(Math.round((b?.price ?? m.price) * total))}원
                      </Text>
                    ) : null}
                  </Pressable>

                  <Pressable
                    onPress={() => openMenu(m)}
                    disabled={blocked}
                    accessibilityRole="button"
                    accessibilityLabel={blocked ? `${m.name} 판매 중지` : `${m.name} 판매 입력`}
                    accessibilityState={{ disabled: blocked }}
                    style={{ flexDirection: 'row', alignItems: 'center', gap: 3, paddingVertical: 9, paddingHorizontal: 16, borderRadius: 10, backgroundColor: blocked ? T.line : T.blue }}
                  >
                    <Icon name="plus" size={16} color={blocked ? T.ter : T.onColor} sw={2.4} />
                    <Text style={{ fontSize: 14, fontWeight: '700', color: blocked ? T.ter : T.onColor }}>판매</Text>
                  </Pressable>
                </View>
              );
            })}
          </Card>
        </QueryState>
      </ScrollView>

      {/* SALES-05 개수 수정 */}
      <Sheet visible={sel != null} onClose={() => setSel(null)} title="오늘의 판매 수량" sub={sel?.name} height={560}>
        {sel ? (
          <View>
            <Text style={{ fontSize: 14, fontWeight: '700', color: T.sub2, marginBottom: 8 }}>판매</Text>
            <Card pad={0} style={{ overflow: 'hidden', marginBottom: 14 }}>
              {([
                ['매장', 'hall'], ['배달', 'delivery'], ['포장', 'takeout'],
              ] as const).map(([n, key], i) => (
                <View key={n} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12, paddingHorizontal: 15, borderBottomWidth: i < 2 ? 1 : 0, borderBottomColor: T.line2 }}>
                  <Text style={{ flex: 1, fontSize: 16, fontWeight: '700', color: T.ink }}>{n}</Text>
                  <SaleStepper label={`${n} 판매량`} value={draft[key]} onChange={(v) => setDraft((d) => ({ ...d, [key]: v }))} />
                </View>
              ))}
            </Card>

            <Text style={{ fontSize: 14, fontWeight: '700', color: T.sub2, marginBottom: 8 }}>폐기</Text>
            <Card pad={0} style={{ overflow: 'hidden', marginBottom: 14 }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12, paddingHorizontal: 15 }}>
                <View style={{ flex: 1, minWidth: 0 }}>
                  <Text style={{ fontSize: 16, fontWeight: '700', color: T.ink }}>조리 폐기</Text>
                  <Text style={{ fontSize: 14, color: T.ter, marginTop: 2 }}>재료는 나가고 매출은 0</Text>
                </View>
                <SaleStepper label="조리 폐기 수량" value={draft.waste} onChange={(v) => setDraft((d) => ({ ...d, waste: v }))} />
              </View>
            </Card>

            <View style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 13, paddingHorizontal: 15, borderRadius: 12, backgroundColor: T.surface2 }}>
              <Text style={{ fontSize: 16, fontWeight: '700', color: T.sub }}>합계</Text>
              <View style={{ flex: 1 }} />
              <Text style={[{ fontSize: 16, fontWeight: '800', color: T.ink }, NUM]}>
                판매 {draftTotal}개{draft.waste > 0 ? ` · 폐기 ${draft.waste}개` : ''}
              </Text>
            </View>
            <Text style={{ fontSize: 14, color: T.sub2, marginTop: 10, lineHeight: 20 }}>
              저장하면 이 메뉴의 레시피대로 식재료 재고가 차감돼요.
            </Text>

            <View style={{ marginTop: 16 }}>
              {/* ⚠ 그날 장부를 못 받았으면 못 누른다. 판본 없이 저장하면 검사가 건너뛰어진다(0117). */}
              <Button kind="primary" size="lg" full disabled={!s} loading={saveSale.isPending} onPress={saveQty}>저장</Button>
            </View>
          </View>
        ) : null}
      </Sheet>

      {/* SALES-06 기타 매출 추가 */}
      <Sheet visible={etcOpen} onClose={() => setEtcOpen(false)} title="기타 매출 추가" sub="레시피에 없는 음료·기타 판매" height={560}>
        {(s?.etcItems.length ?? 0) > 0 ? (
          <Card pad={0} style={{ overflow: 'hidden', marginBottom: 14 }}>
            {s!.etcItems.map((e, i) => (
              <View key={`${e.name}-${i}`} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 11, paddingHorizontal: 15, borderBottomWidth: i < s!.etcItems.length - 1 ? 1 : 0, borderBottomColor: T.line2 }}>
                <View style={{ flex: 1, minWidth: 0 }}>
                  <Text style={{ fontSize: 16, fontWeight: '600', color: T.sub }}>{e.name} <Text style={{ color: T.ter }}>×{e.qty}</Text></Text>
                  {/* 미지정은 회색으로 둔다 — 매장으로 보이면 안 된다(0093). */}
                  <Text style={{ fontSize: 13, fontWeight: '700', color: e.channel ? T.blue : T.ter, marginTop: 2 }}>
                    {channelName(e.channel)}
                  </Text>
                </View>
                <Text style={[{ fontSize: 16, fontWeight: '700', color: T.ink, marginRight: 10 }, NUM]}>{won(e.price * e.qty)}원</Text>
                <Pressable
                  onPress={() => saveSale.mutate(
                    { date: today, items: allItems(), etcItems: s!.etcItems.filter((_, j) => j !== i), baseRevision: s!.revision },
                    { onError: (e) => onSaveError(e, () => {}) })}
                  hitSlop={8} accessibilityRole="button" accessibilityLabel={`${e.name} 삭제`}
                >
                  <Icon name="close" size={16} color={T.ter} />
                </Pressable>
              </View>
            ))}
          </Card>
        ) : null}
        <Field label="항목명" req><Input value={etcName} onChangeText={setEtcName} placeholder="예: 음료" /></Field>
        <View style={{ flexDirection: 'row', gap: 10 }}>
          <View style={{ flex: 1.5 }}><Field label="판매가" req><Input value={etcPrice} onChangeText={setEtcPrice} placeholder="2000" keyboardType="number-pad" suffix="원" mono /></Field></View>
          <View style={{ flex: 1 }}><Field label="수량"><Input value={etcQty} onChangeText={setEtcQty} keyboardType="number-pad" suffix="개" mono /></Field></View>
        </View>
        {/*
          한 줄에 채널 하나다. 소주를 매장·배달 둘 다 팔았으면 두 줄로 적는다 —
          메뉴처럼 3칸으로 쪼개면 음료 하나 넣는 데 숫자를 셋 눌러야 한다.
        */}
        <Field label="판매 채널" req>
          <View style={{ flexDirection: 'row', gap: 7 }}>
            {CHANNEL_LABEL.map(([code, name]) => {
              const on = etcChannel === code;
              return (
                <Pressable
                  key={code}
                  onPress={() => setEtcChannel(code)}
                  accessibilityRole="radio"
                  accessibilityState={{ selected: on }}
                  accessibilityLabel={name}
                  style={{
                    flex: 1, paddingVertical: 12, borderRadius: 11, alignItems: 'center',
                    borderWidth: on ? 1.5 : 1,
                    borderColor: on ? T.blue : T.line,
                    backgroundColor: on ? T.blueTint : T.surface,
                  }}
                >
                  <Text style={{ fontSize: 15, fontWeight: on ? '800' : '600', color: on ? T.blue : T.sub }}>{name}</Text>
                </Pressable>
              );
            })}
          </View>
        </Field>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, paddingVertical: 12, paddingHorizontal: 14, borderRadius: 10, backgroundColor: T.blueTint }}>
          <Icon name="info" size={15} color={T.blue} />
          <Text style={{ flex: 1, fontSize: 14, color: T.sub2, lineHeight: 20 }}>기타 매출은 재료 차감 없이 매출에만 더해져요.</Text>
        </View>
        <View style={{ marginTop: 18 }}>
          <Button kind="primary" size="lg" full disabled={!s} loading={saveSale.isPending} onPress={addEtc}>추가</Button>
        </View>
      </Sheet>

      {/* SALES-07 지출 추가 */}
      <Sheet visible={expOpen} onClose={() => setExpOpen(false)} title="지출 추가" sub="재료비 외 당일 현금 지출" height={580}>
        {(s?.extraItems.length ?? 0) > 0 ? (
          <Card pad={0} style={{ overflow: 'hidden', marginBottom: 14 }}>
            {s!.extraItems.map((e, i) => (
              <View key={`${e.name}-${i}`} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 11, paddingHorizontal: 15, borderBottomWidth: i < s!.extraItems.length - 1 ? 1 : 0, borderBottomColor: T.line2 }}>
                <View style={{ flex: 1, minWidth: 0 }}>
                  <Text style={{ fontSize: 16, fontWeight: '600', color: T.sub }}>{e.name}</Text>
                  {e.memo ? <Text style={{ fontSize: 14, color: T.ter, marginTop: 2 }}>{e.memo}</Text> : null}
                </View>
                <Text style={[{ fontSize: 16, fontWeight: '700', color: T.ink, marginRight: 10 }, NUM]}>{won(e.amount)}원</Text>
                <Pressable
                  onPress={() => saveSale.mutate(
                    { date: today, items: allItems(), extraItems: s!.extraItems.filter((_, j) => j !== i), baseRevision: s!.revision },
                    { onError: (e) => onSaveError(e, () => {}) })}
                  hitSlop={8} accessibilityRole="button" accessibilityLabel={`${e.name} 삭제`}
                >
                  <Icon name="close" size={16} color={T.ter} />
                </Pressable>
              </View>
            ))}
          </Card>
        ) : null}
        <Field label="항목명" req><Input value={expName} onChangeText={setExpName} placeholder="예: 얼음·소모품" /></Field>
        <Field label="금액" req><Input value={expAmount} onChangeText={setExpAmount} placeholder="15000" keyboardType="number-pad" suffix="원" mono /></Field>
        <Field label="메모 (선택)"><Input value={expMemo} onChangeText={setExpMemo} placeholder="간단 메모" /></Field>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, paddingVertical: 12, paddingHorizontal: 14, borderRadius: 10, backgroundColor: T.amberTint }}>
          <Icon name="info" size={15} color={T.amberText} />
          <Text style={{ flex: 1, fontSize: 14, color: T.amberText, lineHeight: 20 }}>그날 손익에서만 차감되고, 고정 지출엔 반영되지 않아요.</Text>
        </View>
        <View style={{ marginTop: 18 }}>
          <Button kind="primary" size="lg" full disabled={!s} loading={saveSale.isPending} onPress={addExpense}>추가</Button>
        </View>
      </Sheet>

      <SortSheet visible={sortOpen} options={SORTS} value={sort} onSelect={setSort} onClose={() => setSortOpen(false)} />


      {/*
        저장 직전 부족 확인 — 막는 게 아니라 알리는 것이다(기획안 §4.4).
        ⚠ `그대로 판매` 는 **한 번만** 저장한다. 경고 때문에 두 번 부르면 재고가 두 번 빠진다.
      */}
      <ShortageWarningSheet
        visible={ask !== null}
        mode="sale"
        recipes={ask?.recipes ?? []}
        loading={saveSale.isPending}
        onCheck={() => { setAsk(null); setSel(null); router.push('/sales/stock-check?mode=sale' as Href); }}
        onContinue={() => { const run = ask?.save; setAsk(null); run?.(); }}
        onClose={() => setAsk(null)}
      />

      {/*
        판매를 저장하려다 '아직 영업 전'으로 막혔을 때 — 시작하고 **이어서** 저장한다.
        두 번 누르게 하지 않는다.
      */}
      <ConfirmSheet
        visible={pendingRetry !== null}
        title="오늘 영업을 시작할까요?"
        message={'지금의 판매가·재료 구성·단가·부자재·고정지출·세금이 오늘 기준으로 정해져요. 영업 중에 메뉴를 고쳐도 오늘 매출에는 반영되지 않고, 다음 영업일부터 적용돼요.'}
        confirmText="영업 시작"
        loading={saveSale.isPending}
        onCancel={() => setPendingRetry(null)}
        onConfirm={() => {
          const retry = pendingRetry;
          setPendingRetry(null);
          /*
           * open RPC 를 따로 부르지 않는다(0154). 재시도가 `openDay=true` 로 저장하고,
           * 서버가 영업 시작 + 저장을 한 트랜잭션으로 한다. 예전 두 번 호출은
           * 열기만 성공하고 저장이 죽으면 빈 영업일을 남겼다.
           */
          retry?.();
        }}
      />

      <LateCloseSheet
        visible={lateRetry !== null}
        timezone={bday.data?.timezone ?? 'Asia/Seoul'}
        loading={saveSale.isPending}
        onCancel={() => setLateRetry(null)}
        onConfirm={(t) => {
          const retry = lateRetry;
          setLateRetry(null);
          retry?.(t);
        }}
      />

      {/* 짧은 알림 — 팝업 대신. 닫으면 사라지고, 남아야 할 것은 상단 안내가 들고 있다. */}
      {toast ? (
        <Pressable
          onPress={() => setToast(null)}
          accessibilityRole="button" accessibilityLabel="알림 닫기"
          style={{ position: 'absolute', left: 16, right: 16, bottom: 24, paddingVertical: 13, paddingHorizontal: 15, borderRadius: 12, backgroundColor: 'rgba(25,31,40,0.92)' }}
        >
          <Text style={{ fontSize: 14, fontWeight: '700', color: '#fff', lineHeight: 20 }}>{toast}</Text>
        </Pressable>
      ) : null}

    </View>
  );
}
